import winston from "winston";
import path from "path";
import fs from "fs";
import util from "util";

const { combine, timestamp, printf, colorize } = winston.format;

/**
 * Available log levels in order of severity (lowest to highest)
 * @typedef {'silly' | 'debug' | 'verbose' | 'info' | 'warn' | 'error' | 'critical'} LogLevel
 */

/**
 * Logger configuration options
 * @typedef {Object} LoggerConfig
 * @property {string} label - Label/context for the logger (e.g., "SSO", "API", etc.)
 * @property {LogLevel} [logLevel="silly"] - Log level threshold. If not specified, logs all levels
 * @property {string} [logFile="application"] - Base name for log file (without extension). Will be appended with date
 * @property {string} [logDir="logs"] - Directory to store log files
 */

/**
 * Logger instance with all logging methods
 * @typedef {Object} LoggerInstance
 * @property {LoggerMethod} error - Log at error level
 * @property {LoggerMethod} warn - Log at warn level
 * @property {LoggerMethod} info - Log at info level
 * @property {LoggerMethod} debug - Log at debug level
 * @property {LoggerMethod} critical - Log at critical level
 * @property {LoggerMethod} verbose - Log at verbose level
 * @property {LoggerMethod} silly - Log at silly level (lowest level)
 */

/**
 * Logger method signature
 * @callback LoggerMethod
 * @param {string} [message] - Log message (optional if passing an object as first argument)
 * @param {...*} [args] - Additional arguments (objects, arrays, etc.) to log
 * @returns {void}
 */

// Define custom log levels with critical included
const customLevels = {
  levels: {
    error: 0,
    warn: 1,
    info: 2,
    verbose: 3,
    debug: 4,
    silly: 5,
    critical: 0, // Same as error level (highest priority)
  },
  colors: {
    error: 'red',
    warn: 'yellow',
    info: 'green',
    verbose: 'cyan',
    debug: 'blue',
    silly: 'magenta',
    critical: 'red bold',
  }
};

// Register the custom levels with winston
winston.addColors(customLevels.colors);

/**
 * Get caller location using Error.stack
 * @param {number} skipFrames - Number of stack frames to skip
 * @returns {string} Formatted location (fileName.js:12:15)
 */
const getCallerLocation = (skipFrames = 3) => {
  try {
    // Create an error to capture the stack
    const err = new Error();
    const stack = err.stack || '';
    const lines = stack.split('\n');
    
    // Skip the first line (Error: ...) and the specified number of frames
    const startIndex = skipFrames + 1; // +1 for the "Error:" line
    
    // Find the first line that doesn't contain internal modules
    for (let i = startIndex; i < lines.length; i++) {
      const line = lines[i];
      
      // Skip lines that contain internal Node.js modules or node_modules
      if (line.includes('node_modules') || 
          line.includes('internal/') || 
          line.includes('module_job') ||
          line.includes('run_main')) {
        continue;
      }
      
      // Parse the stack line: "    at functionName (file.js:12:15)"
      // or "    at file.js:12:15"
      const match = line.match(/\((.*):(\d+):(\d+)\)/) || line.match(/at (.*):(\d+):(\d+)/);
      
      if (match) {
        let filePath = match[1];
        const lineNumber = match[2];
        const columnNumber = match[3];
        
        // Clean up the file path
        if (filePath.startsWith('file://')) {
          filePath = filePath.substring(7);
        }
        
        // Get just the filename
        const fileName = path.basename(filePath);
        return `${fileName}:${lineNumber}:${columnNumber}`;
      }
    }
    
    return "unknown:0:0";
  } catch (error) {
    return "unknown:0:0";
  }
};

/**
 * Format a value for logging
 * @param {*} value - Value to format
 * @returns {string} Formatted string
 */
const formatValue = (value) => {
  if (value === null) return 'null';
  if (value === undefined) return 'undefined';
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (value instanceof Error) return `[Error: ${value.message}]`;
  
  return util.inspect(value, {
    showHidden: false,
    depth: 3,
    colors: false,
    compact: false,
    breakLength: 80,
  });
};

/**
 * Process log arguments and extract message and metadata
 * @param {*} message - Primary message (could be string or object)
 * @param {Array} args - Additional arguments
 * @returns {Object} Processed log data
 * @returns {string} returns.message - Formatted message
 * @returns {Object} returns.meta - Extracted metadata
 */
const processLogArgs = (message, args) => {
  let formattedMessage = '';
  let meta = {};
  let extraParts = [];

  // Case 1: Only object passed (no message string) - logger.info({ ... })
  if (message && typeof message === 'object' && !(message instanceof Error) && args.length === 0) {
    formattedMessage = formatValue(message);
    return { message: formattedMessage, meta: {} };
  }

  // Case 2: Object passed as first argument with additional args - logger.info({ ... }, "extra", ...)
  if (message && typeof message === 'object' && !(message instanceof Error) && args.length > 0) {
    formattedMessage = formatValue(message);
    // Process additional args
    args.forEach((arg) => {
      if (arg === null) {
        extraParts.push('null');
      } else if (arg === undefined) {
        extraParts.push('undefined');
      } else if (typeof arg === 'string') {
        extraParts.push(arg);
      } else if (typeof arg === 'number' || typeof arg === 'boolean') {
        extraParts.push(String(arg));
      } else if (arg instanceof Error) {
        meta.error = {
          name: arg.name,
          message: arg.message,
          stack: arg.stack,
          ...(arg.code ? { code: arg.code } : {}),
        };
        extraParts.push(`[Error: ${arg.message}]`);
      } else if (typeof arg === 'object') {
        Object.assign(meta, arg);
        extraParts.push(formatValue(arg));
      } else {
        extraParts.push(String(arg));
      }
    });
    if (extraParts.length > 0) {
      formattedMessage = `${formattedMessage} ${extraParts.join(' ')}`;
    }
    return { message: formattedMessage, meta };
  }

  // Case 3: String message with args - logger.info("message", ...)
  if (typeof message === 'string' || typeof message === 'number' || typeof message === 'boolean') {
    formattedMessage = String(message);
    args.forEach((arg) => {
      if (arg === null) {
        extraParts.push('null');
      } else if (arg === undefined) {
        extraParts.push('undefined');
      } else if (typeof arg === 'string') {
        extraParts.push(arg);
      } else if (typeof arg === 'number' || typeof arg === 'boolean') {
        extraParts.push(String(arg));
      } else if (arg instanceof Error) {
        meta.error = {
          name: arg.name,
          message: arg.message,
          stack: arg.stack,
          ...(arg.code ? { code: arg.code } : {}),
        };
        extraParts.push(`[Error: ${arg.message}]`);
      } else if (typeof arg === 'object') {
        // For objects, merge into meta and format for display
        Object.assign(meta, arg);
        // Don't add to extraParts to avoid duplication
        // The object will be displayed via meta
      } else {
        extraParts.push(String(arg));
      }
    });
    if (extraParts.length > 0) {
      formattedMessage = `${formattedMessage} ${extraParts.join(' ')}`;
    }
    return { message: formattedMessage, meta };
  }

  // Case 4: No valid message
  return { message: 'No message provided', meta: {} };
};

/**
 * Console log format configuration with colorization
 * @type {winston.Logform.Format}
 */
const consoleFormat = combine(
  colorize(),
  timestamp({ format: "YYYY-MM-DD HH:mm:ss" }),
  printf(({ level, message, label, timestamp, location, ...meta }) => {
    let locationStr = location ? ` \x1b[90m(${location})\x1b[0m` : "";
    
    // If there's additional metadata, format it
    let metaStr = '';
    const metaKeys = Object.keys(meta);
    if (metaKeys.length > 0) {
      // Remove internal fields
      const filteredMeta = {};
      let hasDisplayableMeta = false;
      metaKeys.forEach(key => {
        if (key !== 'label' && key !== 'location' && key !== 'timestamp') {
          filteredMeta[key] = meta[key];
          hasDisplayableMeta = true;
        }
      });
      
      if (hasDisplayableMeta) {
        metaStr = ' ' + util.inspect(filteredMeta, {
          showHidden: false,
          depth: 3,
          colors: true,
          compact: false,
          breakLength: 80,
        });
      }
    }
    
    return `${timestamp} [${label}] ${level}: ${message}${metaStr}${locationStr}`;
  }),
);

/**
 * File log format configuration
 * @type {winston.Logform.Format}
 */
const fileFormat = combine(
  timestamp({ format: "YYYY-MM-DD HH:mm:ss" }),
  printf(({ level, message, label, timestamp, location, ...meta }) => {
    let locationStr = location ? ` (${location})` : "";
    
    // If there's additional metadata, format it
    let metaStr = '';
    const metaKeys = Object.keys(meta);
    if (metaKeys.length > 0) {
      // Remove internal fields
      const filteredMeta = {};
      let hasDisplayableMeta = false;
      metaKeys.forEach(key => {
        if (key !== 'label' && key !== 'location' && key !== 'timestamp') {
          filteredMeta[key] = meta[key];
          hasDisplayableMeta = true;
        }
      });
      
      if (hasDisplayableMeta) {
        metaStr = ' ' + util.inspect(filteredMeta, {
          showHidden: false,
          depth: 3,
          colors: false,
          compact: false,
          breakLength: 80,
        });
      }
    }
    
    return `${timestamp} [${label}] ${level}: ${message}${metaStr}${locationStr}`;
  }),
);

/**
 * Format error objects for structured logging
 * @param {Error|*} error - The error to format
 * @returns {Object} Formatted error object
 */
export const formatErrorForLogs = (error) => {
  if (error instanceof Error) {
    return {
      name: error.name,
      message: error.message,
      stack: error.stack,
      ...(error.code ? { code: error.code } : {}),
    };
  }

  return { rawError: error };
};

/**
 * Get the current date in YYYY-MM-DD format
 * @param {Date} [date=new Date()] - Date to format
 * @returns {string} Formatted date string
 */
const getDateString = (date = new Date()) => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

/**
 * Generate log filename with current date
 * @param {string} baseName - Base name for the log file
 * @param {Date} [date=new Date()] - Date to use for the filename
 * @param {string} [extension=".log"] - File extension
 * @returns {string} Formatted filename
 */
const getLogFilename = (baseName, date = new Date(), extension = ".log") => {
  const dateStr = getDateString(date);
  return `${baseName}-${dateStr}${extension}`;
};

/**
 * Ensure the logs directory exists
 * @param {string} logDir - Directory path for logs
 * @throws {Error} If directory cannot be created
 */
const ensureLogDirectory = (logDir) => {
  try {
    if (!fs.existsSync(logDir)) {
      fs.mkdirSync(logDir, { recursive: true });
    }
  } catch (error) {
    console.error(`Failed to create log directory: ${logDir}`, error);
    throw error;
  }
};

/**
 * Create a logger instance with automatic location tracking and daily log rotation
 * 
 * @param {LoggerConfig} config - Logger configuration
 * @param {string} config.label - Label/context for the logger
 * @param {LogLevel} [config.logLevel="silly"] - Log level threshold
 * @param {string} [config.logFile="application"] - Base name for log file (without extension)
 * @param {string} [config.logDir="logs"] - Directory to store log files
 * 
 * @returns {LoggerInstance} Logger instance with proxied methods
 * 
 * @example
 * const logger = createLogger({
 *   label: "TEST",
 *   logLevel: "debug"
 * });
 * 
 * // Multiple string arguments
 * logger.debug("This will show", "welcome", "to the logger");
 * 
 * // With objects - NO DUPLICATION
 * logger.info("User data", { userId: 123, name: "John" });
 * 
 * // With arrays - NO DUPLICATION
 * logger.debug("Items", [1, 2, 3, 4]);
 * 
 * // Only object (no message) - NO DUPLICATION
 * logger.info({ userId: 123, name: "John" });
 * 
 * // Only object with single property - NO DUPLICATION
 * logger.info({ h: "hoo" });
 * 
 * // With errors
 * try {
 *   throw new Error("Something went wrong");
 * } catch (error) {
 *   logger.error("Operation failed", error);
 * }
 */
export const createLogger = ({ 
  label, 
  logLevel = "silly",
  logFile = "application", 
  logDir = "logs" 
}) => {
  // Ensure the logs directory exists
  ensureLogDirectory(logDir);

  // Generate the log filename with current date
  const today = new Date();
  const filename = getLogFilename(logFile, today);
  const logFilePath = path.join(logDir, filename);

  // Create the base logger with custom levels
  const baseLogger = winston.createLogger({
    levels: customLevels.levels,
    level: logLevel,
    transports: [
      new winston.transports.Console({ 
        format: consoleFormat,
      }),
      new winston.transports.File({
        filename: logFilePath,
        format: fileFormat,
      }),
    ],
    defaultMeta: { label },
  });

  // Create a helper function for logging
  const createLogMethod = (level) => {
    return (message, ...args) => {
      const location = getCallerLocation(2);
      const { message: formattedMessage, meta } = processLogArgs(message, args);
      baseLogger.log(level, formattedMessage, { ...meta, location });
    };
  };

  // Create proxy methods
  return {
    error: createLogMethod('error'),
    warn: createLogMethod('warn'),
    info: createLogMethod('info'),
    debug: createLogMethod('debug'),
    critical: createLogMethod('critical'),
    verbose: createLogMethod('verbose'),
    silly: createLogMethod('silly'),
  };
};

/**
 * Default export for createLogger function
 * @module logger
 * @exports {Function} createLogger
 */
export default createLogger;